    lay("<html style='font-size:20px'><body style='margin:0'><div id=g style='width:600px'><div id=a style='font-size:20px;line-height:1.5;height:10px;width:50px;width:clamp(2.88em, min(14px, 1px, 3rlh, .22rlh), 9px) / 3'>A</div></div></body></html>");
