    TEST_ASSERT_EQUAL(12, el("a")->length[WE_LEN_WIDTH].count);
    TEST_ASSERT_FALSE(diag_has("math length refused"));
    lay("<html style='font-size:16px'><body style='margin:0'><div id=g style='width:600px'><div id=a style='font-size:16px;line-height:20px;height:10px;width:50px;width:max(calc(0em))'>A</div></div></body></html>");
    TEST_ASSERT_EQUAL(0, el("a")->w);
    TEST_ASSERT_EQUAL(1, el("a")->length[WE_LEN_WIDTH].count);
    TEST_ASSERT_FALSE(diag_has("math length refused"));
